--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,12 +1,44 @@
+import { readFileSync, writeFileSync, existsSync } from "fs";
+import { resolve } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_FILE = resolve("./sessions.json");
+const SYNC_INTERVAL_MS = 5000;
+
+let store = new Map<string, Entry>();
+let isDirty = false;
+
+const loadFromDisk = (): void => {
+  try {
+    if (!existsSync(CACHE_FILE)) return;
+    const data = JSON.parse(readFileSync(CACHE_FILE, "utf-8"));
+    store = new Map(Object.entries(data) as [string, Entry][]);
+  } catch (error) {
+    console.error("Failed to load cache from disk:", error);
+  }
+};
+
+const saveToDisk = (): void => {
+  if (!isDirty) return;
+  try {
+    const data = Object.fromEntries(store);
+    writeFileSync(CACHE_FILE, JSON.stringify(data), "utf-8");
+    isDirty = false;
+  } catch (error) {
+    console.error("Failed to save cache to disk:", error);
+  }
+};
+
+loadFromDisk();
+setInterval(saveToDisk, SYNC_INTERVAL_MS);

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  isDirty = true;
 };

